INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l16',3,4,16,'Mary Had a Little Lamb','玛丽有一头小羔羊','介词/动词 + 动名词(-ing)结构:accuse sb of doing(指控某人做)、deny doing(否认做)、be ashamed of doing(为做…羞愧)、apologize for doing(为做…道歉),对比 begin to rain(部分动词后接 to do),外加 had better (not) + 动词原形 表“最好(别)…”的忠告(原创承载 NCE3 L16 考点·美式改写:白羊被偷,丹错怪邻居后道歉,一场雨把染黑的羊毛冲白,真相大白)','玛丽和丈夫丹住在小镇外的一座小农场。玛丽最珍爱的,是丹送她的一只小白羊。白天她把它拴在草地的木桩上,每天傍晚去牵回来。可有天晚上,小羊不见了——拴绳被割断,显然是被偷了。丹从地里回来,玛丽把事情一说,他立刻出门查是谁干的,心想这么小的镇子不难查。四处打听后,他得知邻居厄尔忽然弄来了一只新羊。丹气冲冲地找上门,指控厄尔偷了羊,还警告他最好把羊还回来,否则就报警。厄尔矢口否认,把丹领进后院——他确实刚买了只羊,他说,可他那只是黑的。为错怪了老实人,丹羞愧不已,为自己妄下结论连声道歉。两人正说着,天下起雨来,丹在门廊下躲到雨停。半小时后他走到外面,惊呆了:那只黑羊竟变得几乎全白——原来羊毛是被染黑的,一场雨把它冲干净了!','{"q":"Listen and answer — Why did the black lamb turn white in the rain?","options":["Its wool had been dyed black","It was a magic lamb","Someone swapped the lambs","The rain had bleach in it"],"answer_index":0}'::jsonb,'{"title":"动词/介词 + 动名词 + had better","intro":"①有些动词后面直接接 -ing 形式:deny taking(否认拿)、admit breaking(承认打碎)、enjoy doing。②“介词 + 动名词”很常见:accuse sb of stealing(指控偷)、be ashamed of doing(为…羞愧)、apologize for doing(为…道歉)——介词后面一律用 -ing。③注意有的动词后接 to do:begin to rain、want to go,别和上面混。④had better (not) + 动词原形,表示“最好(别)…”的忠告,语气比 should 强:You had better return it(你最好还回去)/ You had better not go(你最好别去)。","table":{"headers":["用法","意思","例子"],"rows":[["accuse sb of doing","指控某人做了…","accused Earl of stealing it"],["deny doing / admit doing","否认做 / 承认做","denied taking it"],["be ashamed of / apologize for doing","为做…羞愧 / 道歉","ashamed of having accused him"],["had better (not) + 原形","最好(别)…（忠告）","You had better return it."]]},"specialRules":[{"rule":"介词(of / for / about …)后面接动词时,一律用 -ing 形式:apologize for jumping（✓）/ apologize for jump（✗）。","mark":"介词 + doing"},{"rule":"had better 后接动词原形(不带 to);否定是 had better not + 原形:You had better not go。别写成 had better to / had not better。","mark":"had better (not) + 原形"},{"rule":"美语里“后院”常说 backyard(英式 back garden),小镇执法者是 sheriff(警长);get 的过去分词美语用 gotten(英式 got)。","mark":"backyard / sheriff / gotten"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l16',1,NULL,'Mary and her husband Dan lived on a small farm just outside a quiet town. One of Mary''s prize possessions was a little white lamb that Dan had given her. She kept it tied to a post in the meadow during the day and went to bring it in every evening.','玛丽和丈夫丹住在小镇外的一座小农场。玛丽最珍爱的,是丹送她的一只小白羊。白天她把它拴在草地的木桩上,每天傍晚去牵回来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l16',2,NULL,'One evening, however, the lamb was gone. The rope had been cut, so it was obvious that the lamb had been stolen. When Dan came in from the fields, Mary told him what had happened. Dan set out at once to find out who had taken it, sure that in such a small town it would not be hard.','可有天晚上,小羊不见了——拴绳被割断,显然是被偷了。丹从地里回来,玛丽把事情一说,他立刻出门查是谁干的,心想这么小的镇子不难查。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l16',3,NULL,'After asking around, he learned that his neighbor, Earl, had suddenly gotten himself a new lamb. Dan marched over and accused Earl of stealing it, warning him that he had better return it or he would call the sheriff. Earl denied taking anything and led Dan into his backyard.','四处打听后,他得知邻居厄尔忽然弄来了一只新羊。丹气冲冲地找上门,指控厄尔偷了羊,还警告他最好把羊还回来,否则就报警。厄尔矢口否认,把丹领进后院。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l16',4,NULL,'It was true that he had just bought a lamb, he said, but his lamb was black. Ashamed of having accused an innocent man, Dan apologized for jumping to conclusions. While they were talking, it began to rain, and Dan waited under the porch until it stopped.','他确实刚买了只羊,他说,可他那只是黑的。为错怪了老实人,丹羞愧不已,为自己妄下结论连声道歉。两人正说着,天下起雨来,丹在门廊下躲到雨停。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l16',5,NULL,'When he stepped outside half an hour later, he was astonished: the little black lamb had turned almost white. Its wool, which had been dyed black, had been washed clean by the rain!','半小时后他走到外面,惊呆了:那只黑羊竟变得几乎全白——原来羊毛是被染黑的,一场雨把它冲干净了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
