INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l17','be designed by','',NULL,'/bi dɪˈzaɪnd baɪ/','The bridge was designed by Othmar Ammann.','这座桥由阿曼设计。','This app was designed by a small team.','这个应用由一个小团队设计。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l17','be made of','',NULL,'/bi meɪd əv/','The platforms are made of steel and concrete.','这些平台由钢和混凝土制成。','The ring is made of gold.','这枚戒指由黄金制成。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l17','consider sth to be','',NULL,'/kənˈsɪdər tə bi/','Many consider the bridge to be elegant.','许多人认为这座桥很优美。','We consider him to be honest.','我们认为他很诚实。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l17','take into account','',NULL,'/teɪk ˈɪntə əˈkaʊnt/','The designer took the curve of the earth into account.','设计者把地球的弧度考虑了进去。','You must take the cost into account.','你必须把成本考虑进去。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp1','choice','{"stem":"\"The two towers ___ on huge underwater platforms.\"(被动:“被建在”)","options":["built","build","are built","are building"],"answer_index":2,"stem_cn":"两座桥塔建在巨大的水下平台上。","explanation_cn":"被动语态“被建在”用 be + 过去分词,一般现在是 are built。✓ The towers are built on platforms. ✗ build 主动;✗ are building 进行;✗ built 缺 be。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp1','choice','{"stem":"\"The bridge ___ by an engineer named Othmar Ammann.\"(被动过去:“被设计”)","options":["was designing","designs","designed","was designed"],"answer_index":3,"stem_cn":"这座桥由工程师奥斯马·阿曼设计。","explanation_cn":"被动语态“被设计”过去用 was + 过去分词。✓ The bridge was designed by an engineer. ✗ designed 缺 be;✗ was designing 是进行;✗ designs 主动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp1','choice','{"stem":"\"The platforms ___ deep beneath the sea.\"(被动一般现在:“被沉入”)","options":["sank","are sunk","sink","are sinking"],"answer_index":1,"stem_cn":"那些平台深深沉入海底。","explanation_cn":"被动语态“被沉入”一般现在是 are + 过去分词。✓ The platforms are sunk deep. ✗ sink 主动;✗ are sinking 进行;✗ sank 主动过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp2','choice','{"stem":"\"It ___ that the bridge could carry far more cars.\"(被动完成:“据估计”)","options":["estimated","is estimating","has been estimated","has estimated"],"answer_index":2,"stem_cn":"据估计,这座桥能承载多得多的车。","explanation_cn":"被动语态完成时“据估计”用 has been + 过去分词。✓ It has been estimated that… ✗ has estimated 主动;✗ estimated 缺 be;✗ is estimating 进行主动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp2','choice','{"stem":"\"The curve of the earth ___ into account when the bridge was built.\"(被动含情态:“不得不被考虑”)","options":["had to take","had to be taken","has taken","took"],"answer_index":1,"stem_cn":"建桥时不得不把地球的弧度考虑进去。","explanation_cn":"含情态的被动“不得不被考虑”用 had to be + 过去分词。✓ had to be taken into account. ✗ had to take 主动;✗ took 主动;✗ has taken 主动完成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp2','choice','{"stem":"\"The whole roadway ___ from four great cables.\"(被动:“被悬挂”)","options":["is suspended","suspends","suspended","is suspending"],"answer_index":0,"stem_cn":"整个桥面由四根大缆索悬吊着。","explanation_cn":"被动语态“被悬挂”用 be + 过去分词。✓ The roadway is suspended from cables. ✗ suspends 主动;✗ is suspending 进行;✗ suspended 缺 be。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp3','choice','{"stem":"\"The bridge was designed ___ Othmar Ammann.\"(施动者用哪个介词)","options":["from","with","of","by"],"answer_index":3,"stem_cn":"这座桥由阿曼设计。","explanation_cn":"被动语态里引出施动者(动作发出者)用 by。✓ designed by Othmar Ammann. ✗ with(用工具)/ from / of:施动者要用 by。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp3','choice','{"stem":"\"Each cable is made ___ steel wire.\"(“由…制成”用哪个介词)","options":["on","by","of","to"],"answer_index":2,"stem_cn":"每根缆索由钢丝制成。","explanation_cn":"“由某种材料制成”用 be made of。✓ made of steel wire. ✗ by 是施动者;✗ on / to:材料用 of。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp3','choice','{"stem":"\"The bridge is admired ___ millions of drivers every year.\"(施动者用哪个介词)","options":["of","by","to","with"],"answer_index":1,"stem_cn":"每年有数百万司机赞叹这座桥。","explanation_cn":"被动语态里赞叹的“发出者”用 by。✓ admired by millions of drivers. ✗ of / with / to:施动者要用 by。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp4','choice','{"stem":"\"For years it ___ to be the longest bridge in the world.\"(被动 + 不定式:“被认为是”)","options":["considers","was consider","considered","was considered"],"answer_index":3,"stem_cn":"多年来它被认为是世界上最长的桥。","explanation_cn":"“被认为是”用被动 was + 过去分词 + to be。✓ it was considered to be the longest. ✗ considered 缺 be;✗ was consider 形式错;✗ considers 主动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp4','choice','{"stem":"\"Verrazzano is not usually ___ to be a famous explorer.\"(被动 + 不定式:“被认为是”)","options":["thinking","thought","thinks","think"],"answer_index":1,"stem_cn":"韦拉扎诺通常不被认为是著名探险家。","explanation_cn":"“不被认为是”用被动 is + 过去分词:is thought to be。✓ is not usually thought to be famous. ✗ think / thinking / thinks:被动要用过去分词 thought。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp4','choice','{"stem":"\"Many people consider the bridge ___ simple and elegant.\"(consider sth 后接不定式)","options":["to be","is","be","being"],"answer_index":0,"stem_cn":"许多人认为这座桥简洁而优美。","explanation_cn":"consider + 某物 + to be…,后面用不定式 to be。✓ consider the bridge to be elegant. ✗ being / is / be:consider sth 后接 to be。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp5','choice','{"stem":"\"Engineers found the platforms ___ stronger than expected.\"(find sth 后接不定式)","options":["are","to be","being","be"],"answer_index":1,"stem_cn":"工程师发现这些平台比预想的更坚固。","explanation_cn":"find + 某物 + to be…,用不定式 to be。✓ found the platforms to be stronger. ✗ being / are / be:find sth 后接 to be。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp5','choice','{"stem":"\"We know the Verrazzano ___ one of the great bridges of the world.\"(know sth 后接不定式)","options":["to be","being","is","be"],"answer_index":0,"stem_cn":"我们知道韦拉扎诺是世界名桥之一。","explanation_cn":"know + 某物 + to be…,用不定式 to be。✓ know the Verrazzano to be one of the great bridges. ✗ being / is / be:know sth 后接 to be。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp5','choice','{"stem":"\"They estimated the span ___ about 4,260 feet long.\"(estimate sth 后接不定式)","options":["be","being","is","to be"],"answer_index":3,"stem_cn":"他们估计跨度约有4260英尺长。","explanation_cn":"estimate + 某物 + to be…,用不定式 to be。✓ estimated the span to be 4,260 feet. ✗ being / is / be:estimate sth 后接 to be。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp6','choice','{"stem":"\"The distance a bridge stretches across is called its ___.\"(“跨度”用哪个词)","options":["harbor","span","shadow","cloud"],"answer_index":1,"stem_cn":"桥横跨的距离叫跨度。","explanation_cn":"桥横跨的距离叫 span(跨度)。✓ a span of 4,260 feet. ✗ harbor 港口;✗ cloud 云;✗ shadow 影子——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp6','choice','{"stem":"\"A very hard building material made of cement, sand, and stone is ___.\"(“混凝土”用哪个词)","options":["cotton","glass","concrete","paper"],"answer_index":2,"stem_cn":"用水泥、沙、石做的坚硬建材。","explanation_cn":"用水泥、沙、石做的坚硬建材是 concrete(混凝土)。✓ steel and concrete. ✗ cotton 棉;✗ paper 纸;✗ glass 玻璃——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',5,'am3_l17_gp6','choice','{"stem":"\"Something graceful and beautifully simple is ___.\"(“优美别致的”用哪个词)","options":["noisy","cheap","ugly","elegant"],"answer_index":3,"stem_cn":"优雅而简洁美观的。","explanation_cn":"优雅而简洁美观的是 elegant(优美别致的)。✓ simple and elegant. ✗ ugly 丑;✗ noisy 吵;✗ cheap 便宜——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',6,NULL,'choice','{"stem":"suspension 的意思是:","options":["倒塌","悬挂,吊","清洗","挖掘"],"answer_index":1,"explanation_cn":"suspension = 悬挂、吊(suspension bridge 吊桥)。✓ a giant suspension bridge.\n顺带记:倒塌 = collapse;挖掘 = dig;清洗 = wash."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',6,NULL,'choice','{"stem":"span 的意思是:","options":["价格","重量","跨度","颜色"],"answer_index":2,"explanation_cn":"span = 跨度。✓ a span of 4,260 feet 4260英尺的跨度。\n顺带记:重量 = weight;颜色 = color;价格 = price."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',6,NULL,'choice','{"stem":"cable 的意思是:","options":["锚","帆","桨","缆索,钢缆"],"answer_index":3,"explanation_cn":"cable = 缆索、钢缆。✓ four thick cables 四根粗缆。\n顺带记:帆 = sail;桨 = oar;锚 = anchor."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',6,NULL,'choice','{"stem":"estimate 的意思是:","options":["拆除","估计","出售","忘记"],"answer_index":1,"explanation_cn":"estimate = 估计。✓ it has been estimated that… 据估计……。\n顺带记:忘记 = forget;拆除 = demolish;出售 = sell."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',6,NULL,'choice','{"stem":"immensity 的意思是:","options":["巨大","柔软","渺小","明亮"],"answer_index":0,"explanation_cn":"immensity = 巨大。✓ despite its immensity 尽管它无比巨大。\n顺带记:渺小 = smallness;柔软 = softness;明亮 = brightness."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',6,NULL,'choice','{"stem":"elegant 的意思是:","options":["廉价的","粗糙的","危险的","优美别致的"],"answer_index":3,"explanation_cn":"elegant = 优美别致的。✓ simple and elegant 简洁而优美。\n顺带记:粗糙的 = rough;危险的 = dangerous;廉价的 = cheap."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',7,NULL,'cloze','{"stem":"第 1 空","context":"The Verrazzano-Narrows Bridge ___1___ by Othmar Ammann. Its two towers ___2___ on huge platforms of steel and concrete beneath the sea. For many years the bridge ___3___ to be the longest of its kind in the world. It ___4___ that, even packed with cars, it would carry only a fraction of what it can hold.","blank_no":1,"options":["was designed","designed","designs","was designing"],"answer_index":0,"explanation_cn":"被动过去“被设计”用 was + 过去分词。✓ The bridge was designed by Othmar Ammann."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',7,NULL,'cloze','{"stem":"第 2 空","context":"The Verrazzano-Narrows Bridge ___1___ by Othmar Ammann. Its two towers ___2___ on huge platforms of steel and concrete beneath the sea. For many years the bridge ___3___ to be the longest of its kind in the world. It ___4___ that, even packed with cars, it would carry only a fraction of what it can hold.","blank_no":2,"options":["are built","build","built","are building"],"answer_index":0,"explanation_cn":"被动一般现在“被建在”用 are + 过去分词。✓ Its two towers are built on huge platforms."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',7,NULL,'cloze','{"stem":"第 3 空","context":"The Verrazzano-Narrows Bridge ___1___ by Othmar Ammann. Its two towers ___2___ on huge platforms of steel and concrete beneath the sea. For many years the bridge ___3___ to be the longest of its kind in the world. It ___4___ that, even packed with cars, it would carry only a fraction of what it can hold.","blank_no":3,"options":["was considered","considered","considers","was consider"],"answer_index":0,"explanation_cn":"被动 + 不定式“被认为是”用 was considered to be。✓ the bridge was considered to be the longest."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',7,NULL,'cloze','{"stem":"第 4 空","context":"The Verrazzano-Narrows Bridge ___1___ by Othmar Ammann. Its two towers ___2___ on huge platforms of steel and concrete beneath the sea. For many years the bridge ___3___ to be the longest of its kind in the world. It ___4___ that, even packed with cars, it would carry only a fraction of what it can hold.","blank_no":4,"options":["has been estimated","has estimated","estimated","estimates"],"answer_index":0,"explanation_cn":"被动完成“据估计”用 has been + 过去分词。✓ It has been estimated that…"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',8,NULL,'choice','{"stem":"Where is the Verrazzano-Narrows Bridge?","options":["It joins Brooklyn to Staten Island","It crosses the Mississippi River","It links two islands in Boston","It stands in California"],"answer_index":0,"explanation_cn":"课文说 a giant suspension bridge that joins Brooklyn to Staten Island——大桥连接布鲁克林与斯塔滕岛。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',8,NULL,'choice','{"stem":"Why did the bridge''s designer have to think about the shape of the earth?","options":["The cables are thin","The towers are very small","The water is shallow","The bridge is so long"],"answer_index":3,"explanation_cn":"课文说 it is so long that the curve of the earth had to be taken into account——桥太长,所以要把地球弧度算进去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',8,NULL,'choice','{"stem":"According to engineers, how much of its capacity would the bridge use if packed with cars?","options":["All of it","Exactly half","Only a fraction","More than it can hold"],"answer_index":2,"explanation_cn":"课文说 it would still carry only a fraction of what it can hold——即使塞满车,也只用到承载力的一小部分。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',9,NULL,'choice','{"stem":"你想说\"这座桥由阿曼设计\"(被动 + by):","options":["The bridge was design by Othmar Ammann.","The bridge designed by Othmar Ammann.","The bridge was designed by Othmar Ammann.","The bridge is designed of Othmar Ammann."],"answer_index":2,"explanation_cn":"被动语态“被…设计”用 be + 过去分词,施动者用 by。✓ The bridge was designed by Othmar Ammann. 场合:说明某物是由谁做的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',9,NULL,'choice','{"stem":"你想说\"人们认为它是世界名桥之一\"(consider sth to be):","options":["People consider it to be one of the world''s great bridges.","People consider it being one of the world''s great bridges.","People consider it be one of the world''s great bridges.","People consider it is one of the world''s great bridges."],"answer_index":0,"explanation_cn":"consider + 某物 + to be…,后接不定式。✓ People consider it to be one of the world''s great bridges. 场合:表达“认为某物是……”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',9,NULL,'choice','{"stem":"你想说\"建桥时必须把地球的弧度考虑进去\"(被动 + take into account):","options":["The curve of the earth had to be take into account.","The curve of the earth must took into account.","The curve of the earth had to take into account.","The curve of the earth had to be taken into account."],"answer_index":3,"explanation_cn":"含情态的被动“不得不被考虑”用 had to be + 过去分词。✓ The curve of the earth had to be taken into account. 场合:说明某事在设计/施工时被纳入考虑。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"span 的意思是:","options":["价格","重量","颜色","跨度"],"answer_index":3,"explanation_cn":"span = 跨度。✓ a span of 4,260 feet."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"elegant 的意思是:","options":["廉价的","优美别致的","危险的","粗糙的"],"answer_index":1,"explanation_cn":"elegant = 优美别致的。✓ simple and elegant."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"\"The bridge ___ by Othmar Ammann.\"(被动过去)","options":["designed","was designing","was designed","designs"],"answer_index":2,"stem_cn":"这座桥由阿曼设计。","explanation_cn":"被动过去“被设计”用 was + 过去分词。✓ The bridge was designed by Othmar Ammann. ✗ designed 缺 be;✗ designs 主动;✗ was designing 进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"\"For years it ___ to be the longest bridge.\"(被动 + 不定式)","options":["considered","was considered","was consider","considers"],"answer_index":1,"stem_cn":"多年来它被认为是最长的桥。","explanation_cn":"被动 + 不定式“被认为是”用 was considered to be。✓ For years it was considered to be the longest bridge. ✗ considered 缺 be;✗ considers 主动;✗ was consider 形式错。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"\"be made of\" 的意思是:","options":["由…制成","把…卖掉","为…制作","被…忘记"],"answer_index":0,"explanation_cn":"be made of = 由…(材料)制成。✓ made of steel and concrete 由钢和混凝土制成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"\"take into account\" 的意思是:","options":["打开账户","取出存款","把…考虑在内","算错了账"],"answer_index":2,"explanation_cn":"take into account = 把…考虑在内。✓ take the cost into account 把成本考虑进去。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"After whom was the bridge named?","options":["Its engineer","A Brooklyn mayor","A U.S. president","An Italian sailor"],"answer_index":3,"passage":"If you drive south out of Brooklyn, you soon see one of the great sights of New York: the Verrazzano-Narrows Bridge, a giant suspension bridge that joins Brooklyn to Staten Island. For many years it was considered to be the longest suspension bridge on Earth. It was named after Giovanni da Verrazzano, an Italian sailor who is said to have entered New York Harbor back in 1524. Verrazzano is not usually thought to be a famous explorer, yet his name is now known to millions who cross the water each day. The bridge was designed by an engineer named Othmar Ammann. Its main span stretches about 4,260 feet, and it is so long that the curve of the earth had to be taken into account when it was built. Two huge towers, which rise nearly 700 feet above the water, support four thick cables. The towers themselves are held up by enormous platforms of steel and concrete that are sunk deep beneath the sea. Each cable is made of tens of thousands of lengths of wire, and the whole roadway is suspended from them. It has been estimated that even if the bridge were packed bumper to bumper with cars, it would still carry only a fraction of what it can hold. Yet size is not everything. Despite its immensity, the Verrazzano is considered by many to be simple and elegant, a huge object drawn, as its designer hoped, as faintly as possible against the sky.","explanation_cn":"课文说 It was named after Giovanni da Verrazzano, an Italian sailor——大桥以意大利航海家韦拉扎诺命名。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"What holds up the four huge cables?","options":["Floating boats","Two great towers","The roadway itself","Underwater tunnels"],"answer_index":1,"passage":"If you drive south out of Brooklyn, you soon see one of the great sights of New York: the Verrazzano-Narrows Bridge, a giant suspension bridge that joins Brooklyn to Staten Island. For many years it was considered to be the longest suspension bridge on Earth. It was named after Giovanni da Verrazzano, an Italian sailor who is said to have entered New York Harbor back in 1524. Verrazzano is not usually thought to be a famous explorer, yet his name is now known to millions who cross the water each day. The bridge was designed by an engineer named Othmar Ammann. Its main span stretches about 4,260 feet, and it is so long that the curve of the earth had to be taken into account when it was built. Two huge towers, which rise nearly 700 feet above the water, support four thick cables. The towers themselves are held up by enormous platforms of steel and concrete that are sunk deep beneath the sea. Each cable is made of tens of thousands of lengths of wire, and the whole roadway is suspended from them. It has been estimated that even if the bridge were packed bumper to bumper with cars, it would still carry only a fraction of what it can hold. Yet size is not everything. Despite its immensity, the Verrazzano is considered by many to be simple and elegant, a huge object drawn, as its designer hoped, as faintly as possible against the sky.","explanation_cn":"课文说 Two huge towers…support four thick cables——两座大桥塔托起四根粗缆。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"What are the underwater platforms made of?","options":["Wood and rope","Sand and clay","Glass and brick","Steel and concrete"],"answer_index":3,"audio":"If you drive south out of Brooklyn, you soon see one of the great sights of New York: the Verrazzano-Narrows Bridge, a giant suspension bridge that joins Brooklyn to Staten Island. For many years it was considered to be the longest suspension bridge on Earth. It was named after Giovanni da Verrazzano, an Italian sailor who is said to have entered New York Harbor back in 1524. Verrazzano is not usually thought to be a famous explorer, yet his name is now known to millions who cross the water each day. The bridge was designed by an engineer named Othmar Ammann. Its main span stretches about 4,260 feet, and it is so long that the curve of the earth had to be taken into account when it was built. Two huge towers, which rise nearly 700 feet above the water, support four thick cables. The towers themselves are held up by enormous platforms of steel and concrete that are sunk deep beneath the sea. Each cable is made of tens of thousands of lengths of wire, and the whole roadway is suspended from them. It has been estimated that even if the bridge were packed bumper to bumper with cars, it would still carry only a fraction of what it can hold. Yet size is not everything. Despite its immensity, the Verrazzano is considered by many to be simple and elegant, a huge object drawn, as its designer hoped, as faintly as possible against the sky.","explanation_cn":"课文说 enormous platforms of steel and concrete——水下平台由钢和混凝土浇筑。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l17',10,NULL,'choice','{"stem":"Besides being huge, how does the writer describe the bridge?","options":["Dark and heavy","Old and rusty","Simple and elegant","Noisy and crowded"],"answer_index":2,"audio":"If you drive south out of Brooklyn, you soon see one of the great sights of New York: the Verrazzano-Narrows Bridge, a giant suspension bridge that joins Brooklyn to Staten Island. For many years it was considered to be the longest suspension bridge on Earth. It was named after Giovanni da Verrazzano, an Italian sailor who is said to have entered New York Harbor back in 1524. Verrazzano is not usually thought to be a famous explorer, yet his name is now known to millions who cross the water each day. The bridge was designed by an engineer named Othmar Ammann. Its main span stretches about 4,260 feet, and it is so long that the curve of the earth had to be taken into account when it was built. Two huge towers, which rise nearly 700 feet above the water, support four thick cables. The towers themselves are held up by enormous platforms of steel and concrete that are sunk deep beneath the sea. Each cable is made of tens of thousands of lengths of wire, and the whole roadway is suspended from them. It has been estimated that even if the bridge were packed bumper to bumper with cars, it would still carry only a fraction of what it can hold. Yet size is not everything. Despite its immensity, the Verrazzano is considered by many to be simple and elegant, a huge object drawn, as its designer hoped, as faintly as possible against the sky.","explanation_cn":"课文说 the Verrazzano is considered by many to be simple and elegant——除了巨大,作者形容它简洁而优美。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
